-- C-04: fiscal years, calendars and accounting periods.
set local lock_timeout='5s';set local statement_timeout='60s';
create schema fiscal_structure_private;revoke all on schema fiscal_structure_private from public,anon,authenticated,service_role;grant usage on schema fiscal_structure_private to authenticated;
create or replace function organization_master_private.meta(k text)returns table(t text,pk text,links text,fields text[])language sql immutable set search_path=pg_catalog as $$select c.t,c.pk,c.links,c.fields from(values
 ('departments','departments','department_id','department_subsidiaries',array['name','type','parent_id','is_inactive']),('locations','locations','location_id','location_subsidiaries',array['name','parent_id','country_id']),('classes','classes','class_id','class_subsidiaries',array['name','parent_id','description','is_inactive']),('cost-centers','cost_centers','cost_center_id',null,array['name','subsidiary_id','cost_center_type','customer_id','department_id','class_id','up_approver_id']),('financial-creditors','financial_creditors','financial_creditor_id','financial_creditor_subsidiaries',array['name','identification','is_inactive']),('related-companies','related_companies','related_company_id','related_company_subsidiaries',array['name','identification','is_inactive','country_id']),
 ('fiscal-years','fiscal_years','fiscal_year_id',null,array['year_name','start_date','end_date','is_closed']),('fiscal-calendars','fiscal_calendars','fiscal_calendar_id',null,array['calendar_name','fiscal_year_id']),('accounting-periods','fiscal_periods','fiscal_period_id',null,array['period_name','fiscal_year_id','subsidiary_id','start_date','end_date','checklist_completed','ap_closed','ar_closed','gl_closed','is_closed','is_inactive']))c(k,t,pk,links,fields)where c.k=$1$$;
create function fiscal_structure_private.closure_allowed()returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform entity_master_private.identity();return exists(select 1 from public.role_permissions rp join public.permissions p using(permission_id)where rp.role_id=public.app_active_role_id()and p.code='CONF_PERIODOS_FISCALES_CERRAR');end$$;
create function fiscal_structure_private.scope_ids(k text,id bigint)returns bigint[]language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare r bigint[];begin
 if k='accounting-periods'then select array[subsidiary_id]into r from public.fiscal_periods where fiscal_period_id=id;
 elsif k='fiscal-calendars'then select array_agg(subsidiary_id order by subsidiary_id)into r from public.subsidiaries where fiscal_calendar_id=id;
 else select array_agg(distinct sid order by sid)into r from(select subsidiary_id sid from public.fiscal_periods where fiscal_year_id=id union select s.subsidiary_id from public.subsidiaries s join public.fiscal_calendars c using(fiscal_calendar_id)where c.fiscal_year_id=id)x;end if;return coalesce(r,'{}');end$$;
create function fiscal_structure_private.writable(k text,id bigint)returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select not exists(select 1 from unnest(fiscal_structure_private.scope_ids(k,id))x where not exists(select 1 from public.user_subsidiaries us where us.user_id=public.app_user_id()and us.subsidiary_id=x))$$;
create function fiscal_structure_private.visible(k text,sid bigint)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare active bigint:=entity_master_private.identity();begin return organization_master_private.allowed(k,'view')and(k<>'accounting-periods'or sid=active);exception when insufficient_privilege then return false;end$$;
create function fiscal_structure_private.fingerprint(k text,id bigint)returns text language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare c record;r jsonb;refs jsonb;begin select *into c from organization_master_private.meta(k);execute format('select to_jsonb(x)from public.%I x where %I=$1',c.t,c.pk)into r using id;
 if k='fiscal-years'then select coalesce(jsonb_agg(to_jsonb(p)order by fiscal_period_id),'[]')into refs from public.fiscal_periods p where fiscal_year_id=id;
 elsif k='accounting-periods'then select jsonb_build_array(y.start_date,y.end_date,y.is_closed)into refs from public.fiscal_years y where y.fiscal_year_id=(r->>'fiscal_year_id')::bigint;end if;
 return md5(jsonb_build_array(r,refs,fiscal_structure_private.scope_ids(k,id))::text);end$$;
create function fiscal_structure_private.dto(k text,id bigint)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare c record;r jsonb;begin select *into c from organization_master_private.meta(k);execute format('select to_jsonb(x)from public.%I x where %I=$1',c.t,c.pk)into r using id;return r||jsonb_build_object('_revision',fiscal_structure_private.fingerprint(k,id),'_actions',jsonb_build_object('canEdit',organization_master_private.allowed(k,'edit')and fiscal_structure_private.writable(k,id),'canDelete',organization_master_private.allowed(k,'delete')and fiscal_structure_private.writable(k,id)and not entity_master_private.used(c.t,id)));end$$;
create function fiscal_structure_private.list(k text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare c record;r jsonb;begin perform organization_master_private.access(k,'view');select *into c from organization_master_private.meta(k);execute format('select coalesce(jsonb_agg(fiscal_structure_private.dto($1,%I)order by %I),''[]'')from public.%I where fiscal_structure_private.visible($1,%s)',c.pk,c.pk,c.t,case when k='accounting-periods'then'subsidiary_id'else'null::bigint'end)into r using k;return r;end$$;
create function fiscal_structure_private.options(k text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform organization_master_private.access(k,'view');return jsonb_build_object('canView',true,'canCreate',organization_master_private.allowed(k,'create'),'canEdit',organization_master_private.allowed(k,'edit'),'canDelete',organization_master_private.allowed(k,'delete'),'canManageClosure',fiscal_structure_private.closure_allowed(),'references',jsonb_build_object(
 'organization/subsidiaries',coalesce((select jsonb_agg(jsonb_build_object('subsidiary_id',s.subsidiary_id,'name',s.name))from public.subsidiaries s join public.user_subsidiaries us using(subsidiary_id)where us.user_id=public.app_user_id()and s.is_active),'[]'),
 'organization/fiscal-years',coalesce((select jsonb_agg(jsonb_build_object('fiscal_year_id',fiscal_year_id,'year_name',year_name,'start_date',start_date,'end_date',end_date,'is_closed',is_closed))from public.fiscal_years),'[]')));end$$;
create function fiscal_structure_private.date_value(v text)returns date language plpgsql immutable set search_path=pg_catalog as $$begin if coalesce(v,'')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'then raise exception using errcode='22023',message='Fecha inválida.';end if;return v::date;end$$;
create function fiscal_structure_private.batch(p jsonb)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=organization_master_private.access('accounting-periods','create');subs bigint[];sub bigint;y public.fiscal_years;m date;a date;b date;e public.fiscal_periods;first_id bigint;created int:=0;existing int:=0;yearid bigint;begin
 if jsonb_typeof(p)is distinct from'object'or pg_column_size(p)>32000 or exists(select 1 from jsonb_object_keys(p)x where x not in('fiscal_year_id','subsidiary_ids'))or coalesce(p->>'fiscal_year_id','')!~'^[1-9][0-9]{0,15}$'then raise exception using errcode='22023',message='Seleccione año fiscal y filiales.';end if;
 perform pg_advisory_xact_lock(793150,1);subs:=entity_master_private.ids(p->'subsidiary_ids');yearid:=(p->>'fiscal_year_id')::bigint;
 if not sid=any(subs)or exists(select 1 from unnest(subs)x where not exists(select 1 from public.subsidiaries s join public.user_subsidiaries us using(subsidiary_id)where s.subsidiary_id=x and s.is_active and us.user_id=public.app_user_id()))then raise exception using errcode='42501',message='Filiales no autorizadas o falta la actual.';end if;
 select *into y from public.fiscal_years where fiscal_year_id=yearid for share;if not found or y.is_closed then raise exception using errcode='55000',message='Año no disponible o cerrado.';end if;
 if y.start_date is null or y.end_date is null or y.end_date<y.start_date or y.end_date-y.start_date>400 then raise exception using errcode='22023',message='Rango fiscal inválido para generar períodos.';end if;
 foreach sub in array subs loop m:=date_trunc('month',y.start_date)::date;while m<=y.end_date loop a:=greatest(m,y.start_date);b:=least((m+interval'1 month'-interval'1 day')::date,y.end_date);
 select *into e from public.fiscal_periods where subsidiary_id=sub and fiscal_year_id=yearid and start_date=a and end_date=b;
 if found then existing:=existing+1;
 else if exists(select 1 from public.fiscal_periods where subsidiary_id=sub and daterange(start_date,end_date,'[]')&&daterange(a,b,'[]'))then raise exception using errcode='55000',message='Un período existente se superpone. Revise los rangos.';end if;
 insert into public.fiscal_periods(period_name,start_date,end_date,fiscal_year_id,subsidiary_id,checklist_completed,ap_closed,ar_closed,gl_closed,is_closed,is_inactive)values((array['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'])[extract(month from a)::int]||' '||extract(year from a)::int::text,a,b,yearid,sub,false,false,false,false,false,false)returning *into e;created:=created+1;first_id:=coalesce(first_id,e.fiscal_period_id);end if;m:=(m+interval'1 month')::date;end loop;end loop;
 if created=0 then raise exception using errcode='55000',message='Los períodos seleccionados ya existen.';end if;return fiscal_structure_private.dto('accounting-periods',first_id)||jsonb_build_object('_created_count',created,'_existing_count',existing);end$$;
create function fiscal_structure_private.save(k text,p jsonb,id bigint)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare c record;sid bigint;oldrow jsonb;data jsonb;r jsonb;field text;namefield text;cols text;vals text;sets text;a date;b date;y public.fiscal_years;used boolean;changed_closure boolean:=false;yearid bigint;begin
 if k='accounting-periods'and id is null then return fiscal_structure_private.batch(p);end if;
 sid:=organization_master_private.access(k,case when id is null then'create'else'edit'end);select *into c from organization_master_private.meta(k);
 if id<=0 or id>9007199254740991 or jsonb_typeof(p)is distinct from'object'or pg_column_size(p)>32000 or exists(select 1 from jsonb_object_keys(p)x where not x=any(c.fields||array['_revision']))then raise exception using errcode='22023',message='Campos de estructura fiscal inválidos.';end if;perform pg_advisory_xact_lock(793150,1);
 if id is not null then execute format('select to_jsonb(x)from public.%I x where %I=$1 for update',c.t,c.pk)into oldrow using id;if oldrow is null or(k='accounting-periods'and(oldrow->>'subsidiary_id')::bigint<>sid)or not fiscal_structure_private.writable(k,id)then raise exception using errcode='42501',message='Estructura fiscal compartida o ajena no autorizada.';end if;if p->>'_revision'is distinct from fiscal_structure_private.fingerprint(k,id)then raise exception using errcode='55000',message='La estructura fiscal cambió. Consúltela nuevamente.';end if;end if;
 data:=coalesce(oldrow,jsonb_build_object('is_closed',false))||(p-'_revision');namefield:=case k when'fiscal-years'then'year_name'when'fiscal-calendars'then'calendar_name'else'period_name'end;
 if jsonb_typeof(data->namefield)is distinct from'string'or nullif(btrim(data->>namefield),'')is null or length(btrim(data->>namefield))>250 then raise exception using errcode='22023',message='Nombre fiscal inválido.';end if;data:=jsonb_set(data,array[namefield],to_jsonb(btrim(data->>namefield)));
 if k<>'fiscal-calendars'then
 foreach field in array case when k='fiscal-years'then array['is_closed']else array['checklist_completed','ap_closed','ar_closed','gl_closed','is_closed','is_inactive']end loop
 if jsonb_typeof(data->field)is distinct from'boolean'then raise exception using errcode='22023',message='Las opciones de cierre deben ser booleanas.';end if;
 if data->field is distinct from coalesce(oldrow->field,'false'::jsonb)then changed_closure:=true;end if;end loop;
 if changed_closure and not fiscal_structure_private.closure_allowed()then raise exception using errcode='42501',message='Requiere permiso específico de cierre fiscal.';end if;
 a:=fiscal_structure_private.date_value(data->>'start_date');b:=fiscal_structure_private.date_value(data->>'end_date');if b<a or b-a>400 then raise exception using errcode='22023',message='Rango fiscal inválido.';end if;
 end if;
 used:=id is not null and entity_master_private.used(c.t,id);
 if k='fiscal-years'then
 if used and(data->>'start_date'is distinct from oldrow->>'start_date'or data->>'end_date'is distinct from oldrow->>'end_date')then raise exception using errcode='55000',message='El año utilizado conserva sus fechas.';end if;
 if(data->>'is_closed')::boolean and exists(select 1 from public.fiscal_periods where fiscal_year_id=id and not is_closed)then raise exception using errcode='55000',message='Cierre todos los períodos antes de cerrar el año.';end if;
 elsif k='fiscal-calendars'then
 if coalesce(data->>'fiscal_year_id','')!~'^[1-9][0-9]{0,15}$'then raise exception using errcode='22023',message='Año fiscal inválido.';end if;yearid:=(data->>'fiscal_year_id')::bigint;
 if not exists(select 1 from public.fiscal_years where fiscal_year_id=yearid)then raise exception using errcode='42501',message='Año fiscal no disponible.';end if;
 if used and data->>'fiscal_year_id'is distinct from oldrow->>'fiscal_year_id'then raise exception using errcode='55000',message='El calendario asignado conserva su año.';end if;
 else
 foreach field in array array['fiscal_year_id','subsidiary_id']loop if coalesce(data->>field,'')!~'^[1-9][0-9]{0,15}$'then raise exception using errcode='22023',message='Origen de período inválido.';end if;end loop;
 if(data->>'subsidiary_id')::bigint is distinct from sid then raise exception using errcode='42501',message='El período conserva la filial activa.';end if;yearid:=(data->>'fiscal_year_id')::bigint;select *into y from public.fiscal_years where fiscal_year_id=yearid for share;
 if not found or a<y.start_date or b>y.end_date then raise exception using errcode='22023',message='El período debe estar dentro del año fiscal.';end if;
 if y.is_closed and(changed_closure or data->>'start_date'is distinct from oldrow->>'start_date'or data->>'end_date'is distinct from oldrow->>'end_date'or data->>'fiscal_year_id'is distinct from oldrow->>'fiscal_year_id')then raise exception using errcode='55000',message='Reabra el año antes de modificar el cierre del período.';end if;
 if used and(data->>'start_date'is distinct from oldrow->>'start_date'or data->>'end_date'is distinct from oldrow->>'end_date'or data->>'fiscal_year_id'is distinct from oldrow->>'fiscal_year_id'or(not coalesce((oldrow->>'is_inactive')::boolean,false)and(data->>'is_inactive')::boolean))then raise exception using errcode='55000',message='El período utilizado conserva fechas, año y estado activo.';end if;
 if(data->>'gl_closed')::boolean and not((data->>'ap_closed')::boolean and(data->>'ar_closed')::boolean)or(data->>'is_closed')::boolean and not((data->>'ap_closed')::boolean and(data->>'ar_closed')::boolean and(data->>'gl_closed')::boolean)then raise exception using errcode='22023',message='Respete la secuencia de cierre AP, AR y GL.';end if;
 end if;
 select string_agg(format('%I',x),','),string_agg(format('v.%I',x),','),string_agg(format('%I=v.%I',x,x),',')into cols,vals,sets from unnest(c.fields)x;
 if id is null then execute format('insert into public.%I(%s)select %s from jsonb_populate_record(null::public.%I,$1)v returning to_jsonb(%I.*)',c.t,cols,vals,c.t,c.t)into r using data;id:=(r->>c.pk)::bigint;
 else execute format('update public.%I x set %s from jsonb_populate_record(null::public.%I,$1)v where x.%I=$2 returning to_jsonb(x)',c.t,sets,c.t,c.pk)into r using data,id;end if;return fiscal_structure_private.dto(k,id);end$$;
create function fiscal_structure_private.remove(k text,id bigint,revision text)returns boolean language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare c record;r jsonb;sid bigint:=organization_master_private.access(k,'delete');begin perform pg_advisory_xact_lock(793150,1);select *into c from organization_master_private.meta(k);execute format('select to_jsonb(x)from public.%I x where %I=$1 for update',c.t,c.pk)into r using id;if r is null or(k='accounting-periods'and(r->>'subsidiary_id')::bigint<>sid)or not fiscal_structure_private.writable(k,id)then raise exception using errcode='42501',message='Estructura fiscal no autorizada.';end if;if revision is distinct from fiscal_structure_private.fingerprint(k,id)or entity_master_private.used(c.t,id)or coalesce((r->>'is_closed')::boolean,false)then raise exception using errcode='55000',message='La estructura cambió, está cerrada o tiene dependencias.';end if;execute format('delete from public.%I where %I=$1',c.t,c.pk)using id;return true;end$$;
create or replace function public.organization_master_list(p_catalog text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_catalog in('fiscal-years','fiscal-calendars','accounting-periods')then return fiscal_structure_private.list(p_catalog);elsif p_catalog='cost-centers'then return cost_center_master_private.list();end if;return organization_master_private.organization_master_list(p_catalog);end$$;
create or replace function public.organization_master_options(p_catalog text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_catalog in('fiscal-years','fiscal-calendars','accounting-periods')then return fiscal_structure_private.options(p_catalog);elsif p_catalog in('financial-creditors','related-companies')then return financial_entity_master_private.options(p_catalog);elsif p_catalog='cost-centers'then return cost_center_master_private.options();end if;return organization_master_private.organization_master_options(p_catalog);end$$;
create or replace function public.save_organization_master(p_catalog text,p_payload jsonb,p_id bigint default null)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_catalog in('fiscal-years','fiscal-calendars','accounting-periods')then return fiscal_structure_private.save(p_catalog,p_payload,p_id);elsif p_catalog in('financial-creditors','related-companies')then return financial_entity_master_private.save(p_catalog,p_payload,p_id);elsif p_catalog='cost-centers'then return cost_center_master_private.save(p_payload,p_id);end if;return organization_master_private.save_organization_master(p_catalog,p_payload,p_id);end$$;
create or replace function public.delete_organization_master(p_catalog text,p_id bigint,p_revision text default null)returns boolean language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_catalog in('fiscal-years','fiscal-calendars','accounting-periods')then return fiscal_structure_private.remove(p_catalog,p_id,p_revision);elsif p_catalog='cost-centers'then return cost_center_master_private.remove(p_id,p_revision);end if;return organization_master_private.delete_organization_master(p_catalog,p_id,p_revision);end$$;
alter function public.validate_accounting_period()set search_path=pg_catalog,public,pg_temp;
do $$declare t text;k text;p record;col record;begin foreach t in array array['fiscal_years','fiscal_calendars','fiscal_periods']loop k:=case t when'fiscal_years'then'fiscal-years'when'fiscal_calendars'then'fiscal-calendars'else'accounting-periods'end;
 for p in select policyname from pg_policies where schemaname='public'and tablename=t loop execute format('drop policy %I on public.%I',p.policyname,t);end loop;execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
 for col in select column_name from information_schema.columns where table_schema='public'and table_name=t loop execute format('revoke insert(%I),update(%I),select(%I),references(%I)on public.%I from public,anon,authenticated,service_role',col.column_name,col.column_name,col.column_name,col.column_name,t);end loop;
 execute format('create policy fiscal_structure_read on public.%I for select to authenticated using(fiscal_structure_private.visible(%L,%s))',t,k,case when t='fiscal_periods'then'subsidiary_id'else'null::bigint'end);execute format('grant select on public.%I to authenticated',t);end loop;end$$;
revoke all on all functions in schema fiscal_structure_private from public,anon,authenticated,service_role;grant execute on function fiscal_structure_private.visible(text,bigint)to authenticated;
revoke all on function public.organization_master_list(text),public.organization_master_options(text),public.save_organization_master(text,jsonb,bigint),public.delete_organization_master(text,bigint,text)from public,anon,authenticated,service_role;
grant execute on function public.organization_master_list(text),public.organization_master_options(text),public.save_organization_master(text,jsonb,bigint),public.delete_organization_master(text,bigint,text)to authenticated;
notify pgrst,'reload schema';
